  height: 380px;
}
#knife-vis canvas.scene-canvas,
#pipeline-vis canvas.scene-canvas,
#thickness-vis canvas.scene-canvas,
#smoke-vis canvas.scene-canvas,
#dose-vis canvas.scene-canvas,
