.use-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 0.45rem;
  margin: 0.6rem 0;
}
.use-grid button {
  text-align: left;
  min-height: 4.2rem;
}
.readout {
  font-variant-numeric: tabular-nums;
  font-family: ui-monospace, Menlo, monospace;
  background: #111;
  color: #9cffb0;
  padding: 0.25rem 0.55rem;
}
table.compact.pair.use-table thead th:first-child,
table.compact.pair.use-table tbody td:first-child {
  width: 22%;
}
.tf-item {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 0.4rem;
  align-items: start;
  margin: 0.35rem 0;
}
.tf-item p { margin: 0; }
.chapter-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 0.9rem;
}
.chapter-cards a {
  display: block;
  text-decoration: none;
  color: inherit;
  background: var(--panel);
  border: 1px solid var(--rule);
  padding: 1rem 1.05rem 1.15rem;
  min-height: 11rem;
}
.chapter-cards a:hover { border-color: var(--teal); }
.chapter-cards svg { width: 100%; height: 88px; }

